}

"use client";

import { EssayDocument, Message, hitsToSources } from "@/lib/actions";
import { PaperPlaneRight } from "@phosphor-icons/react";
import autosize from "autosize";
import {
  KeyboardEventHandler,
  useContext,
  useEffect,
  useRef,
  useState,
} from "react";
